client_script:
frappe.web_form.after_load = () => {
    // Hide navbar and footer
    let navbar = document.querySelector(".navbar");
    let footer = document.querySelector(".web-footer");
    if (navbar) navbar.style.display = "none";
    if (footer) footer.style.display = "none";
};

frappe.web_form.after_save = () => {
    // Redirect after successful submission
    setTimeout(() => {
        window.location.href = "https://erp.mislerp.site/inco-2025-inquiries";
    }, 1000); // 2-second delay to show success message
};

custom_css:
/* General Styles */
body {
    font-family: 'Arial', sans-serif;
    background-color: #0a214f;
    /*color: white;*/
    margin: 10px;
    padding: 0;
    /*text-align: center;*/
    /*height: 100vh;*/
    display: flex;
    justify-content: center; /* Center horizontally */
    align-items: center; /* Center vertically */
}

.page_content{
    margin-top:3rem;
}

#introduction p{
    margin-bottom:0px;
}


/* Form group adjustments */
.form-group {
    margin-bottom: 10px; /* Reduced spacing */
    text-align: left;
}

.form-group label {
    color: #0A214F;
    font-size: 14px; /* Smaller font */
    margin-bottom: 3px; /* Reduced margin */
    display: block;
}


.form-control:focus {
    outline: none;
    box-shadow: 0 0 5px rgba(0, 174, 204, 0.5);
}


/* Button Styles */
.btn-primary, .btn-success {
    display: block;
    width: 150px; /* Reduced width */
    margin: 10px auto; /* Reduced margin */
    padding: 8px 15px; /* Reduced padding */
    background: #00aecc;
    color: white;
    font-size: 16px;
    font-weight: bold;
    border: none;
    border-radius: 5px;
    cursor: pointer;
    transition: background 0.3s ease;
}

.btn-primary:hover, .btn-success:hover {
    background: #007a99;
}

/* Hide unnecessary elements */
.page-header-actions-block {
    display: none !important;
}

.chat-app { 
    display: none; 
} 

/* Responsive Design */
@media screen and (max-width: 768px) {
    .web-form {
        width: 90%; /* Override fixed width */
        height: auto; /* Allow height to adjust */
        padding: 10px;
    }

    .form-group {
        margin-bottom: 8px;
    }

    .form-control {
        font-size: 12px;
        padding: 6px;
        height: 28px;
    }

    .form-group .ql-editor{
        height: 20px;
    }

    .btn-primary, .btn-success {
        width: 95%;
        font-size: 25px;
    }

    
}
